param([Parameter(Mandatory=$true)][string]$Build)
$ErrorActionPreference='Stop';$root=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent;$p="$root/analysis/parallel-aa-receiver/m6-aoa"
Add-Type -AssemblyName System.IO.Compression.FileSystem;Add-Type -Path @("$root/scripts/RdxDex.cs","$root/scripts/RdxDexApi.cs")
$r=Get-Content "$Build/build-report.json" -Raw|ConvertFrom-Json;if((Get-FileHash $r.apk).Hash-ne$r.sha256-or$r.liveExecutionEnabled){throw 'M6 frozen artifact/live policy mismatch'}
foreach($f in $r.sourceHashes+$r.testHashes+$r.fixtureHashes+$r.assetHashes){if((Get-FileHash -LiteralPath $f.Path).Hash-ne$f.Hash){throw 'Untested M6 input changed'}}
$dex=[RdxOffline.Dex]::new([IO.File]::ReadAllBytes("$Build/dex/classes.dex"));$refs=@($dex.Methods|ForEach-Object {$_.Class+'->'+$_.Name+$_.Prototype})
$bad=@($refs|Where-Object {$_-match'->(claimInterface|releaseInterface|bulkTransfer|resetDevice|reset|loadLibrary|createSocket|requestWait|queue)\(|Landroid/media/|Landroid/view/(Surface|SurfaceView|WindowManager)|Landroid/provider/Settings|Landroid/webkit|Ljava/net/|Ljavax/net/ssl|Lcom/honda|Ljava/lang/Runtime;->exec|Ljava/lang/ProcessBuilder'})
if($bad.Count){$bad|Set-Content "$Build/forbidden.txt";throw 'Forbidden M6 APK references'}
if(@($dex.Strings|Where-Object {$_-match'libautoreceiver_jni|/data/misc/gal|com\.honda\.|BOOT_COMPLETED|ACCESSORY_AUDIO|forceClaim|TLS_HANDSHAK|SERVICE_DISCOVERY'}).Count){throw 'M6 forbidden strings'}
$manifest=Get-Content "$Build/manifest-tree.txt" -Raw;if($manifest-match'E: (uses-permission|receiver|activity|provider|intent-filter)\b'-or@([regex]::Matches($manifest,'E: service\b')).Count-ne1-or$manifest-match'sharedUserId'){throw 'M6 manifest privilege/component mismatch'}
$badging=Get-Content "$Build/badging.txt" -Raw;if($badging-notmatch"package: name='com.rdx.fullscreen.m6aoa' versionCode='1' versionName='0.1.0-m6-aoa-only-frozen'"-or$badging-notmatch"(?m)^sdkVersion:'22'"-or$badging-notmatch"(?m)^targetSdkVersion:'22'"){throw 'Actual packaged M6 identity/SDK mismatch'}
$zip=[IO.Compression.ZipFile]::OpenRead($r.apk);try{$extra=@($zip.Entries|Where-Object {$_.FullName-notlike'META-INF/*'-and$_.FullName-notin@('AndroidManifest.xml','classes.dex','assets/project-reviewer.cer','resources.arsc')});if($extra.Count){throw 'Unexpected M6 APK payload/native/private/proof asset'}}finally{$zip.Dispose()}
$adapter=Get-Content "$p/source/com/rdx/fullscreen/m6aoa/AndroidAoaAdapter.java" -Raw
$calls=@([regex]::Matches($adapter,'connection\.controlTransfer\(([^;]+)\);')|ForEach-Object {$_.Groups[1].Value})
$expected=@('192,51,0,0,b,2,1000','64,52,0,r.index,b,b.length,1000','64,53,0,0,null,0,1000');if(@(Compare-Object $calls $expected).Count-or$calls.Count-ne3){throw 'Unapproved controlTransfer callsite'}
$dump=Get-Content "$Build/dexdump.txt" -Raw;$invokes=@([regex]::Matches($dump,'(?m)^.*invoke-.*UsbDeviceConnection;\.controlTransfer.*$')|ForEach-Object Value);if($invokes.Count-ne3){throw "Expected3 actual DEX control callsites, found$($invokes.Count)"}
if((Get-Content "$p/source/com/rdx/fullscreen/m6aoa/LiveExecutionPolicy.java" -Raw)-notmatch'EXECUTION_ENABLED=false;' -or $dump-notmatch'M6_LIVE_DISABLED_FROZEN_RELEASE'){throw 'Missing non-overridable live block'}
$definitions=[Collections.Generic.HashSet[string]]::new();$parents=@{}
foreach($name in @('core-libart.jar','framework.jar')){$zip=[IO.Compression.ZipFile]::OpenRead("$root/adb/RDX-Audit/framework/$name");try{foreach($e in $zip.Entries|Where-Object FullName -match '^classes\d*\.dex$'){$s=$e.Open();$m=[IO.MemoryStream]::new();try{$s.CopyTo($m);$api=[RdxOffline.DexApi]::new([RdxOffline.Dex]::new($m.ToArray()));foreach($d in $api.Definitions){[void]$definitions.Add($d)};foreach($pair in $api.Parents.GetEnumerator()){$parents[$pair.Key]=@($pair.Value)}}finally{$s.Dispose();$m.Dispose()}}}finally{$zip.Dispose()}}
function ResolveMethod([string]$Type,[string]$Suffix,[Collections.Generic.HashSet[string]]$Seen){if(-not$Seen.Add($Type)){return $false};if($definitions.Contains($Type+'->'+$Suffix)){return $true};if($Suffix.StartsWith('<init>')){return $false};foreach($parent in $parents[$Type]){if(ResolveMethod $parent $Suffix $Seen){return $true}};return $false}
$defined=@($dex.DefinedClasses());$apiRows=@(foreach($ref in $refs){$parts=$ref-split'->',2;if($parts[0]-in$defined){continue};$intrinsic=$parts[0].StartsWith('[')-and$parts[1]-eq'clone()Ljava/lang/Object;';[pscustomobject]@{method=$ref;API22=($intrinsic-or(ResolveMethod $parts[0] $parts[1] ([Collections.Generic.HashSet[string]]::new())))}})
$apiRows|ConvertTo-Json|Set-Content "$Build/api22-methods.json";if(@($apiRows|Where-Object API22 -ne $true).Count){$apiRows|Where-Object API22 -ne $true|Format-Table;throw 'M6 API22 unresolved'}
if(@($defined|Where-Object {-not$_.StartsWith('Lcom/rdx/fullscreen/m6aoa/')-or$_-match'M6Tests|Fake|ReviewSigner|M5ReviewProofTool|M6EvidenceTool'}).Count){throw 'Host-only/non-M6 code leaked into DEX'}
$invokes|Set-Content "$Build/control-transfer-callsites.txt"
$result=[ordered]@{PASS=$true;scope='STATIC APK ONLY; no runtime or USB';apk=$r.apk;sha256=$r.sha256;DEX=$r.DEX;modules=$r.modules;definedClasses=$defined.Count;externalAPI22Methods=$apiRows.Count;Java7='PASS';D8min22='PASS';requestedPermissions=@();components=@('com.rdx.fullscreen.m6aoa/.M6AoaService');liveExecutionEnabled=$false;allowedUsb=@('getDeviceList','hasPermission','requestPermission_once','openDevice_once_normal_authorized','controlTransfer51_52_53_only','close');controlCallsites=$calls;maxStarts=1;maxControlTransfers=8;forbidden=$bad;M5gate='Pinned project review signature + canonical metadata + bundle SHA256; no real PASS proof created';ordinaryApp='No shared UID; expected untrusted_app, not runtime measured'}
$result|ConvertTo-Json -Depth 7|Set-Content "$Build/static-audit.json";$result|ConvertTo-Json -Depth 7
